#include <bits/stdc++.h>
using namespace std;
int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n,m;
    cin>>n>>m;
    int a[10]; for(int i=0;i<10;i++) cin>>a[i];
    vector<vector<int>> adj(n+1), radj(n+1);
    for(int i=0;i<m;i++){int u,v;cin>>u>>v;adj[u].push_back(v);radj[v].push_back(u);}
    for(int i=1;i<=n;i++){sort(adj[i].begin(),adj[i].end());sort(radj[i].begin(),radj[i].end());}
    auto has=[&](int u,int v){return binary_search(adj[u].begin(),adj[u].end(),v);};
    auto now=chrono::steady_clock::now;
    auto st=now();
    auto ms=[&]{return chrono::duration_cast<chrono::milliseconds>(now()-st).count();};
    mt19937 rng(42);
    vector<int> best;
    auto try_start=[&](int sv){
        vector<bool> used(n+1,false);
        deque<int> dq; dq.push_back(sv); used[sv]=true;
        auto ext_back=[&]()->bool{
            int c=dq.back(),bv=-1,bs=1e9;
            for(int v:adj[c])if(!used[v]){int s=0;for(int w:adj[v])if(!used[w])s++;if(s<bs||(s==bs&&(rng()&1))){bs=s;bv=v;}}
            if(bv<0)return false; used[bv]=true; dq.push_back(bv); return true;
        };
        auto ext_front=[&]()->bool{
            int c=dq.front(),bv=-1,bs=1e9;
            for(int v:radj[c])if(!used[v]){int s=0;for(int w:radj[v])if(!used[w])s++;if(s<bs||(s==bs&&(rng()&1))){bs=s;bv=v;}}
            if(bv<0)return false; used[bv]=true; dq.push_front(bv); return true;
        };
        for(int r=0;r<5;r++){while(ext_back());while(ext_front());}
        // rotation attempts
        for(int it=0;it<200&&ms()<3800;it++){
            vector<int> p(dq.begin(),dq.end());
            int sz=p.size();
            unordered_map<int,int> pos; for(int i=0;i<sz;i++) pos[p[i]]=i;
            bool did=false;
            // tail rotation
            {int t=p[sz-1];
            vector<int> cands; for(int v:adj[t])if(pos.count(v)&&pos[v]<sz-1)cands.push_back(pos[v]);
            if(!cands.empty()){int j=cands[rng()%cands.size()];
            for(int i=j+1;i<sz;i++)used[p[i]]=false;
            dq.clear(); for(int i=0;i<=j;i++)dq.push_back(p[i]);
            dq.push_back(t); used[t]=true;
            for(int r2=0;r2<3;r2++){while(ext_back());while(ext_front());}
            did=true;}}
            if(!did){int h=p[0];
            vector<int> cands;for(int v:radj[h])if(pos.count(v)&&pos[v]>0)cands.push_back(pos[v]);
            if(!cands.empty()){int j=cands[rng()%cands.size()];
            for(int i=0;i<j;i++)used[p[i]]=false;
            dq.clear();dq.push_back(h);used[h]=true;for(int i=j;i<sz;i++)dq.push_back(p[i]);
            for(int r2=0;r2<3;r2++){while(ext_front());while(ext_back());}
            }}
        }
        // vertex insertion
        {vector<int> p(dq.begin(),dq.end());
        for(int v=1;v<=n;v++)if(!used[v]){
            if(has(v,p[0])){p.insert(p.begin(),v);used[v]=true;continue;}
            if(has(p.back(),v)){p.push_back(v);used[v]=true;continue;}
            for(int i=0;i+1<(int)p.size();i++)if(has(p[i],v)&&has(v,p[i+1])){p.insert(p.begin()+i+1,v);used[v]=true;break;}
        }
        if((int)p.size()>(int)best.size())best=p;}
    };
    vector<int> order(n);iota(order.begin(),order.end(),1);
    shuffle(order.begin(),order.end(),rng);
    for(int i=0;i<n&&ms()<3800;i++){
        try_start(order[i]);
        if((int)best.size()>=n)break;
    }
    cout<<best.size()<<"\n";
    for(int i=0;i<(int)best.size();i++){if(i)cout<<' ';cout<<best[i];}
    cout<<"\n";
}
